#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeSpace: FfiConverter {
    typealias FfiType = UInt64
    typealias SwiftType = Space

    public static func lift(_ handle: UInt64) throws -> Space {
        return Space(unsafeFromHandle: handle)
    }

    public static func lower(_ value: Space) -> UInt64 {
        return value.uniffiCloneHandle()
    }

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> Space {
        let handle: UInt64 = try readInt(&buf)
        return try lift(handle)
    }

    public static func write(_ value: Space, into buf: inout [UInt8]) {
        writeInt(&buf, lower(value))
    }
}


