 */

public enum Arrival: Equatable, Hashable {

    /**
     * A space: its streams follow.
     */
    case space(
        /**
         * The space's ID.
         */space: String
    )
    /**
     * A stream of a space.
     */
    case stream(
        /**
         * The space's ID.
         */space: String,
        /**
         * The stream's ID.
         */stream: String
